INSERT INTO pc_mig_records (batch_id,airtable_table,airtable_record_id,payload_json) VALUES (@pc_batch_id,'SOURCES','rec9SBzzKDB0XiSV7','{"id":"rec9SBzzKDB0XiSV7","createdTime":"2026-10-12T07:16:19.000Z","fields":{"fld0Nk2kian9esxpi":"B. J. Slot","fld97NyQXiOHXFO5X":"Slot, Archipelagus turbatus (1982), pp. 194, 196, 200, 408, 410 as cited by Koutzakiotis 2023.","fldIpMqmpccrtkaNw":"Only a review of Slot checked; general corsair context, not direct evidence for Kythnos 1672. Original book remains to be checked.","fldLkij4WOZbCNmp5":"B. J. Slot, Archipelagus turbatus (1982)","fldReV9xSSFdrkngn":"Unverified","fldYagHDMHivkUSwV":"https://leblog.maisondeloutra.fr/2021/01/archipelagus-turbatus-par-b-j-slot.html","fldrZreK133f1r176":"1982","fldya7i6qPLxnrr6Y":"Secondary"}}') ON DUPLICATE KEY UPDATE payload_json=VALUES(payload_json);
INSERT INTO pc_mig_records (batch_id,airtable_table,airtable_record_id,payload_json) VALUES (@pc_batch_id,'SOURCES','recIhFkr7c1l6SOFs','{"id":"recIhFkr7c1l6SOFs","createdTime":"2026-10-12T07:39:59.000Z","fields":{"fld0Nk2kian9esxpi":"Jacob Spon (letter); edited online by Correspondance de Jacob Spon","fld97NyQXiOHXFO5X":"Bibliothèque nationale de France, ms. français 9360, fols. 235r–236r, Jacob Spon to Claude Nicaise, Lyon, 24 Feb 1680; full diplomatic transcription at Correspondance de Jacob Spon (Version 2). Also printed by Henri Omont, Athènes au XVIIe siècle (1901), pp. c. 16–17.","fldIpMqmpccrtkaNw":"DIRECTLY READ modern scholarly transcription of 1680 original letter, fol.235r: Spon says Chataignier was captured and killed by ''Corsaires de Thermia'' three or four months earlier. Spon names separate informants: cousin Chataignier in Lyon, M. Galland of Candia, Father Babin of Smyrna. Manuscript image NOT directly inspected; editorial transcription checked. Date approximate Oct–Nov 1679. Does NOT establish Crevelier 1672, raid ON Kythnos, or exact location of capture. ''de Thermia'' could mean based at/associated with Thermia, not necessarily an event on the island. Next chase the named informants and BnF ms image.","fldLkij4WOZbCNmp5":"Jacob Spon to Claude Nicaise, Lyon, 24 February 1680 — corsaires de Thermia","fldReV9xSSFdrkngn":"Checked","fldYagHDMHivkUSwV":"https://correspondancejacobspon.wordpress.com/1680-02-24-jacob-spon-a-claude-nicaise/","fldndOGDISoB2vkGQ":["recCmjnf06Gma3r4b"],"fldrZreK133f1r176":"1680","fldya7i6qPLxnrr6Y":"Primary"}}') ON DUPLICATE KEY UPDATE payload_json=VALUES(payload_json);
INSERT INTO pc_mig_records (batch_id,airtable_table,airtable_record_id,payload_json) VALUES (@pc_batch_id,'SOURCES','recMq2SjwQYhE5pjv','{"id":"recMq2SjwQYhE5pjv","createdTime":"2026-10-12T07:45:58.000Z","fields":{"fld0Nk2kian9esxpi":"Jacob Spon; scholarly transcription Correspondance de Jacob Spon","fld97NyQXiOHXFO5X":"Jacob Spon to Claude Nicaise, 12 Jan 1680, edited original-text transcription at Correspondance de Jacob Spon. Manuscript folio to be checked from full header.","fldIpMqmpccrtkaNw":"Contemporaneous letter original-text transcription states François Chataigner, French consul in Athens, was captured and killed by ''Corsaires de Thermia'' while traveling from Corinth to Athens at the notorious Sciron passage. Editorial note dates death early October 1679. This REVISES prior tentative spatial interpretation: incident on mainland Corinth-Athens passage, NOT demonstrated raid on Kythnos. This is SAME AUTHOR/related information chain as Spon Feb 24, not an independent witness. Manuscript image not directly inspected.","fldLkij4WOZbCNmp5":"Jacob Spon → Claude Nicaise, 12 January 1680, François Chastaignier killed by corsairs of Thermia near Scironian passage","fldReV9xSSFdrkngn":"Checked","fldYagHDMHivkUSwV":"https://correspondancejacobspon.wordpress.com/1680-01-12-jacob-spon-a-claude-nicaise/","fldndOGDISoB2vkGQ":["recCmjnf06Gma3r4b"],"fldrZreK133f1r176":"1680","fldya7i6qPLxnrr6Y":"Primary"}}') ON DUPLICATE KEY UPDATE payload_json=VALUES(payload_json);
INSERT INTO pc_mig_records (batch_id,airtable_table,airtable_record_id,payload_json) VALUES (@pc_batch_id,'SOURCES','recNMYli8IVUkuObn','{"id":"recNMYli8IVUkuObn","createdTime":"2026-10-12T07:16:19.000Z","fields":{"fld0Nk2kian9esxpi":"Γιώργος Κουτζακιώτης","fld97NyQXiOHXFO5X":"Βαθύ Αστυπάλαιας, τ. 1 (2023), σ. 218–233, ιδιαίτερα σ. 218–221 και σημ. 7–19.","fldIpMqmpccrtkaNw":"Full searchable PDF checked: death 24–25 Sep 1679 Astypalaia; cites Saulger 1698 pp. 305, 310, 314, 317 and Slot 1982 pp. 194, 196, 200. No occurrence of Κύθνο/Θερμ in searchable text; not Kythnos corroboration.","fldLkij4WOZbCNmp5":"Γ. Κουτζακιώτης (2023), Με αφορμή τον θάνατο του Creveliers στην Αστυπάλαια","fldReV9xSSFdrkngn":"Checked","fldYagHDMHivkUSwV":"https://helios-eie.ekt.gr/EIE/bitstream/10442/18865/1/Koutzakiotis%202023.pdf","fldrZreK133f1r176":"2023","fldya7i6qPLxnrr6Y":"Secondary"}}') ON DUPLICATE KEY UPDATE payload_json=VALUES(payload_json);
