INSERT INTO pc_mig_records (batch_id,airtable_table,airtable_record_id,payload_json) VALUES (@pc_batch_id,'SOURCES','recScPK1aq1s0g7kl','{"id":"recScPK1aq1s0g7kl","createdTime":"2026-10-12T07:47:54.000Z","fields":{"fld0Nk2kian9esxpi":"Jacques-Paul Babin; ed. Henri Omont","fld97NyQXiOHXFO5X":"Henri Omont, Athènes au XVIIe siècle (Paris: Leroux, 1901), pp.16–21, Babin letter 2 Apr 1680; text available on French Wikisource.","fldIpMqmpccrtkaNw":"Published transcription directly read. Babin mentions consuls Chastanier and Giraud in retrospective context and Galland in Smyrna; DOES NOT recount Chastaignier murder or corsaires de Thermia. Thus no independent corroboration for the c.1679 killing. Exact autograph manuscript not directly inspected.","fldLkij4WOZbCNmp5":"Jacques-Paul Babin to Jacob Spon, 2 April 1680 — letter edited by Henri Omont (1901)","fldReV9xSSFdrkngn":"Checked","fldYagHDMHivkUSwV":"https://fr.wikisource.org/wiki/Ath%C3%A8nes_au_XVIIe_si%C3%A8cle/Lettres_de_Jacob_Spon_et_du_P._Babin","fldrZreK133f1r176":"1680","fldya7i6qPLxnrr6Y":"Primary"}}') ON DUPLICATE KEY UPDATE payload_json=VALUES(payload_json);
