INSERT INTO pc_mig_records (batch_id,airtable_table,airtable_record_id,payload_json) VALUES (@pc_batch_id,'SOURCES','recryEv16bNHLX50o','{"id":"recryEv16bNHLX50o","createdTime":"2026-10-12T07:16:19.000Z","fields":{"fld0Nk2kian9esxpi":"Robert Saulger","fld97NyQXiOHXFO5X":"Saulger, Histoire nouvelle..., Paris 1698/1699, pp. 305, 310, 314, 317 as cited by Koutzakiotis 2023.","fldIpMqmpccrtkaNw":"Digital edition located, but original relevant pages not inspected for Kythnos. Primary-text check outstanding.","fldLkij4WOZbCNmp5":"Robert Saulger, Histoire nouvelle des anciens ducs et autres souverains de l''Archipel (1698/1699)","fldReV9xSSFdrkngn":"Unverified","fldYagHDMHivkUSwV":"https://books.google.com/books?id=geSFAAdaUZ4C","fldrZreK133f1r176":"1698/1699","fldya7i6qPLxnrr6Y":"Primary"}}') ON DUPLICATE KEY UPDATE payload_json=VALUES(payload_json);
INSERT INTO pc_mig_records (batch_id,airtable_table,airtable_record_id,payload_json) VALUES (@pc_batch_id,'EVENTS','recCmjnf06Gma3r4b','{"id":"recCmjnf06Gma3r4b","createdTime":"2026-10-12T07:40:05.000Z","fields":{"fld64OaQgjLGbXBPU":"Candidate","fld6QfqVNiOfu4E8v":"Mainland route Corinth–Athens, Scironian passage (exact site unverified); perpetrators described as ''of Thermia/Kythnos''","fldC5Z8YLh6GwEk4N":["recIhFkr7c1l6SOFs","recMq2SjwQYhE5pjv"],"fldHJS3jVXmTyPKPq":"CORRECTED geographic interpretation: not on Kythnos, but along mainland Corinth–Athens route. Exact capture location requires historical Scironian road evidence. Both letters are from same Spon chain. Reported informants not yet independently inspected; manuscript facsimiles not checked. No coordinates.","fldOUDmVcE9a3Rhr5":"Corsair Activity","fldVWYatolwq17NHa":"François Chastaignier (French consul in Athens); unidentified ''corsaires de Thermia''; Jacob Spon","fldVmnmxWbM1CFuWZ":2,"fldWVuhJJH5AvyTAx":"François Chastaignier killed by ''corsaires de Thermia'' on Corinth–Athens passage (c. Oct 1679)","fldcu4IwZ7LvRhV69":1,"fldtMLLeVODTrDXDC":"Spon''s letter of 12 Jan 1680 explicitly places Chastaignier''s capture on his journey from Corinth to Athens at the Scironian passage. His 24 Feb letter confirms report and names three informants. The 12 Jan letter''s modern editor dates death early October 1679. These are two letters by same author, not two independent chains. This is NOT an attack ON Kythnos.","fldu9LmyWh9wQOOvT":"Early October 1679 (editorial dating); reported 12 Jan and 24 Feb 1680"}}') ON DUPLICATE KEY UPDATE payload_json=VALUES(payload_json);
INSERT INTO pc_mig_records (batch_id,airtable_table,airtable_record_id,payload_json) VALUES (@pc_batch_id,'RESEARCH_JOBS','recS8oBkBEXq838Zh','{"id":"recS8oBkBEXq838Zh","createdTime":"2026-10-12T07:06:41.000Z","fields":{"fld2xNHNQxiGQ3RPT":1,"fld7h9nGdPSwIEuVq":"PCT AGENT TREE v2.1 — PARALLEL MULTI-AGENT RESEARCH. General architecture now defines 10 parallel source-family research lanes: (1) Travellers & contemporary Mediterranean/Eastern Mediterranean literature, (2) Spanish Monarchy/Simancas, (3) Venetian, (4) French, (5) English/British, (6) Dutch, (7) German-speaking repositories, (8) Italian states, (9) Ottoman, (10) North African/Barbary. Each lane inherits EVENT-FIRST, actor-optional, century-adaptive, multilingual/historical-variant discovery and feeds the common Citation Chase/acquisition/exact-page/original-inspection/genealogy/corroboration/Verification pipeline. GitHub workflow uses a matrix with max-parallel 10. Kythnos is validation data only, never hard-coded research architecture.","fld9JITu5dsCrYaSH":"Research","fld9zKGW8ANIAI5Du":"Inspected","fldAu6jBerV2neN3c":"Robert Saulger, Histoire nouvelle des anciens ducs et autres souverains de l''Archipel (1698/1699), BSB digital object bsb10447069. Primary scan acquired directly through BSB IIIF Presentation/Image APIs; not inferred from Google/Anemi mirrors.","fldH9R544Mr4uZTbq":"Ερεύνησε Κύθνο 1600–1700","fldJKXXs189Y3dHpX":"2026-10-12T07:06:41.000Z","fldJYQ8GT9XjpN0jO":"2026-10-12T09:44:47.000Z","fldOQOp9ajO9ahvvb":14,"fldP186lZvAp4bpf0":"Acquisition genealogy: Anemi metadata → BSB bsb10447069; Google Books/Play xytCAAAAcAAJ derives from Bavarian State Library digitization; these are not independent textual witnesses merely because exposed by different portals. Bibliotheca Augustana is a separate transcription surface but incomplete (Livre I only). 1698/1699 labels may refer to same edition/date issue and must not be counted as separate evidence.","fldPDwBkAVA2YtGSw":"Continue EVENT-FIRST Citation Chase for all Kythnos/Thermia raids and coercive maritime violence, 1600–1700, across digitized libraries/archives. Expand multilingual event terms and actor-neutral searches; map candidates to exact original pages and independently corroborate. Do not prioritize Crevelier except where a source itself leads to him.","fldRETsQ8EsaQGdWm":"Saulger BSB bsb10447069, printed pages 305, 310,311,312,313,314,315,316,317,318,319, exact-page images from BSB IIIF, visually inspected. Acquisition run 38225186922, artifact 11736105656.","fldRTD4bi0aTa79mx":"ARCHIVAL FINDING: EIE Cyclades archival guide reports extant local Kythnos municipal holdings only from early 19th century; therefore 1672 evidence more likely in external Venetian/French/Ottoman/Capuchin or published contemporary records. Candidate primary leads from Koutzakiotis 2023 notes: Gazette 1673 pp857–858; ANF AE B/I 862 fol75v; BSB Cod.gall.728 pp53,56; Naxos Capuchins notes as printed Markopolis 1893 pp109–110. These are leads NOT inspected/verified for Kythnos. Saulger continuation 7 pages acquired automatically; visual inspection still pending.","flda0afuCpXk2kPnT":true,"fldeTIEfrbJ2EaE6H":"Workflow trial completed (research -> sources -> verification -> QA). Five source records saved. Claim: Crevelier attacked Kythnos in 1672, attested in one checked secondary web narrative, but no checked primary evidence and fewer than 3 demonstrably independent supporting sources. Andros 1672 is a separate reported raid. No verified EVENTS, ROUTES or coordinates were created. Gate result: BLOCKED / NEEDS EVIDENCE. Next research target: Saulger and Slot; check original pages, independent corroboration and precise locations before promotion to Verified.","fldgsMK6Vx2rl6kLK":"DIRECT VISUAL INSPECTION COMPLETE Saulger BSB printed pp.305,310–319 (except 306–309, which were not requested). Newly inspected pp311–313: Creveliers'' early career, 500 men, 12 cannon, failed Mani/Magne expedition. p315: narrative states raid on Metelin/Lesbos; Mani attack dated 12 March 1676. p316 explicitly states ''Au mois d''Octobre de l''année 1678'' beginning death narrative (modern research Koutzakiotis corrects to 1679). p317: Creveliers at Stampalia/Astypalaia; Adam sets fuse in powder magazine. p318: powder explosion, ship destroyed and Creveliers killed; Turkish rejoicing. p319: author''s moral reflection then new section JEAN CAPSI. NO mention of Thermia/Kythnos or Kythnos 1672 raid in inspected Creveliers sequence pp310–319. These pages establish other named island events, NOT Kythnos.","fldhtL4dMwWqpq62w":"Pending","fldk6lLcNFUP6D202":"IIIF acquisition path operational. Generic workflow: .github/workflows/iiif-source-acquisition.yml in Lepe12/geraki-historical-atlas. Inputs: manifest, pages, optional source_id. Output: citation-chase-<run_id> artifact containing exact page images + report.json. Saulger validation succeeded on printed pp.305,310,314,317 mapped uniquely to scans 323,328,332,335. Next Citation Chase step: visually inspect acquired originals before recording claims.","fldl6BrmBsAMtm73U":"1600–1700","fldmPzWboxkkW0r6p":9,"fldn0A8f7eHmAs1KA":"Κύθνος","fldoR4xvrLQjBMUMC":"Unknown","fldoReuZhHL7lqOSi":"Primary Saulger p310 author explicitly claims personal acquaintance with Creveliers. That establishes proximity, NOT eyewitness corroboration of every claim. His fleet-size, 14-year control, contributions and Paros refuge remain author assertions until independently corroborated. Koutzakiotis 2023 gives corrected death 24–25 September 1679 based on modern source criticism. Source genealogy must not count secondary repetition of Saulger as independent.","fldopxbas38oUQUvz":"v2.0 GENERAL GATES: Begin with contemporary travellers/observers and period books plus parallel multinational archival discovery appropriate to century/place. Simancas, Venetian, French, British, Dutch, German, Italian, Ottoman and North African/Barbary source families are standing discovery targets, expanded or weighted by historical context. Search original languages and historical variants. Do not infer actor. UNKNOWN is valid. Catalogue/OCR/later quotation/acquisition is lead only. VERIFIED requires exact original-page inspection, source genealogy and independent corroboration.","fldt6xqFfmGIWkBvw":"Verified primary source discrepancy: Saulger p316 prints OCTOBER 1678 for death episode; Koutzakiotis 2023 reconstructs Sept 24–25 1679. Do not silently harmonize. Direct image reading p315 gives 12 March 1676 Mani expedition and Metelin episode; neither is Kythnos. Pages 310–319 inspected; no explicit Kythnos/Thermia raid.","fldusiOcaalr6CaJW":"PCT-AGENT-TREE v2.1 PARALLEL 10-LANE MULTI-AGENT","fldzpTYfFaSeeTuUK":"More leads available","fldztuhHphR6V0ceV":"2026-10-12: Automated acquisition validated (run 38224732391 SUCCESS). Continuation acquisition run 38225186922 SUCCESS. Added tools/citation_chase_auto.py commit 226fad4355d7a2d81a7e0c9265654ff80a3512e9 and chained it into automatic IIIF workflow commit 98c5c49abd2a7a383852e4fc106e8ae611d0e4ce. Workflow now emits machine-readable Citation Chase state after acquisition, while retaining visual/original inspection and verification gates."}}') ON DUPLICATE KEY UPDATE payload_json=VALUES(payload_json);
